//! UUID helpers ported from Go `base/utils/uuid.go`.
//!
//! The Go package uses `github.com/gofrs/uuid` v4.4.0. `uuid::Uuid::new_v5`
//! implements the same RFC 4122 SHA-1 based algorithm, so the textual output is
//! byte-for-byte identical (verified against reference vectors generated by
//! the Go implementation; see the tests).

use std::sync::OnceLock;

use uuid::Uuid;

/// Namespace used by [`derived_uuid`].
///
/// Go: `uuid.Must(uuid.FromString("e8dba9f7-21e2-4c82-96cb-6586922c6422"))`.
pub const CONSTANT_UUID: Uuid = Uuid::from_u128(0xe8dba9f721e24c8296cb6586922c6422);

/// Namespace for the per-process instance UUID.
const INSTANCE_NAMESPACE: &str = "instance";

static INSTANCE_UUID: OnceLock<Uuid> = OnceLock::new();

/// Returns a new random UUID, optionally mixing `ns` into it.
///
/// Matches Go's `RandomUUID`:
/// * a cryptographically random v4 UUID is generated first;
/// * when `ns` is non-empty the result is a v5 UUID over that random UUID and
///   `ns` (so different calls with the same namespace still differ);
/// * if randomness is unavailable (practically impossible), Go falls back to
///   `NewV5(uuidFromTime(), ns)`. The same fallback is used here.
pub fn random_uuid(ns: &str) -> Uuid {
    match random_v4() {
        Some(random) => {
            if ns.is_empty() {
                random
            } else {
                Uuid::new_v5(&random, ns.as_bytes())
            }
        }
        None => Uuid::new_v5(&uuid_from_time(), ns.as_bytes()),
    }
}

/// Returns a UUID derived only from `input`, reproducible across processes.
///
/// Equivalent to Go's `DerivedUUID`.
pub fn derived_uuid(input: &str) -> Uuid {
    Uuid::new_v5(&CONSTANT_UUID, input.as_bytes())
}

/// Returns a UUID derived from `input`, unique per process execution.
///
/// Equivalent to Go's `DerivedInstanceUUID`. The instance namespace is itself
/// a random v5 UUID computed once at startup, just like Go's package-level
/// `instanceUUID = RandomUUID("instance")`.
pub fn derived_instance_uuid(input: &str) -> Uuid {
    Uuid::new_v5(instance_uuid(), input.as_bytes())
}

/// Returns the process-wide instance namespace.
pub fn instance_uuid() -> &'static Uuid {
    INSTANCE_UUID.get_or_init(|| random_uuid(INSTANCE_NAMESPACE))
}

/// Generates a v4 UUID from crypto-quality randomness, or `None` on failure.
fn random_v4() -> Option<Uuid> {
    let mut bytes = [0u8; 16];
    getrandom::fill(&mut bytes).ok()?;
    // gofrs/uuid.NewV4 sets the version and variant bits exactly like this.
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Some(Uuid::from_bytes(bytes))
}

/// Builds the time-based fallback UUID used when randomness is unavailable.
///
/// Go writes `uint64(time.Now().UnixNano())` into the first eight bytes in
/// *little endian* order and leaves the rest zero.
fn uuid_from_nanos(nanos: i64) -> Uuid {
    let mut bytes = [0u8; 16];
    bytes[..8].copy_from_slice(&(nanos as u64).to_le_bytes());
    Uuid::from_bytes(bytes)
}

fn uuid_from_time() -> Uuid {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_nanos() as i64)
        .unwrap_or(0);
    uuid_from_nanos(nanos)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn constant_uuid_matches_go() {
        assert_eq!(
            CONSTANT_UUID.to_string(),
            "e8dba9f7-21e2-4c82-96cb-6586922c6422"
        );
    }

    #[test]
    fn derived_uuid_matches_go_reference_vectors() {
        // Generated with github.com/gofrs/uuid v4.4.0 via
        // uuid.NewV5(constantUUID, name).
        let cases = [
            ("f", "0d669def-f3f4-523c-ac78-b14b39db65ec"),
            ("f3", "5fe46165-70ee-50e9-9c41-57abe282daec"),
            ("", "99f60162-32a1-5bce-bb38-48eea08e9e0e"),
            ("EVENT", "7d88681e-c3ed-518e-b323-151dc5b0128b"),
            ("event", "7a1b112c-d5fe-5472-8832-87aef1bf879b"),
            (
                "TG8UkxS+4rVrDxHtDAaNab1CBpygzmX1g5mJA37jbQ5q2uE4rVrDxHtDAaNab1CBpygzmX1g5mJA37jbQ5q2uE",
                "f9efb1d0-fc7a-5402-89cc-614a2d3230fa",
            ),
        ];
        for (input, expected) in cases {
            assert_eq!(derived_uuid(input).to_string(), expected, "input {input:?}");
        }
    }

    #[test]
    fn derived_uuid_is_reproducible_and_distinguishes_inputs() {
        assert_eq!(derived_uuid("f"), derived_uuid("f"));
        assert_ne!(derived_uuid("f"), derived_uuid("f3"));
        // The name is case-sensitive, exactly as in Go.
        assert_ne!(derived_uuid("EVENT"), derived_uuid("event"));
    }

    #[test]
    fn time_uuid_matches_go_little_endian_layout() {
        let nanos = 1_700_000_000_123_456_789;
        let time_uuid = uuid_from_nanos(nanos);
        assert_eq!(time_uuid.to_string(), "15cd853d-fe9c-9717-0000-000000000000");
        // Then NewV5 over that namespace, matching Go's mixing test.
        assert_eq!(
            Uuid::new_v5(&time_uuid, b"e").to_string(),
            "e1f03051-96ac-53d8-9c2b-6d3497b26a67"
        );
        assert_eq!(
            Uuid::new_v5(&time_uuid, b"e2").to_string(),
            "ba37a384-78de-5fad-8ccd-8a58a9804cad"
        );
    }

    #[test]
    fn v5_mixing_matches_go_reference() {
        // Fixed "random" v4 UUID: bytes 00 01 .. 0f.
        let random = Uuid::from_bytes([
            0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d,
            0x0e, 0x0f,
        ]);
        assert_eq!(
            Uuid::new_v5(&random, b"ns").to_string(),
            "b45ad1d3-1e95-579b-92d1-9469bac31dcb"
        );
        assert_eq!(
            Uuid::new_v5(&Uuid::nil(), b"x").to_string(),
            "f3e951bb-a80b-5e6c-a038-a56ee0caa25d"
        );
    }

    #[test]
    fn random_uuid_is_random_with_and_without_namespace() {
        let a = random_uuid("");
        let b = random_uuid("");
        assert_ne!(a, b);
        assert_eq!(a.get_version_num(), 4);

        let c = random_uuid("b");
        let d = random_uuid("b");
        assert_ne!(c, d);
        assert_eq!(c.get_version_num(), 5);

        // Long namespaces are accepted, just like in Go.
        let long = "TG8UkxS+4rVrDxHtDAaNab1CBpygzmX1g5mJA37jbQ5q2uE4rVrDxHtDAaNab1CBpygzmX1g5mJA37jbQ5q2uE";
        assert_ne!(random_uuid(long), random_uuid(long));
    }

    #[test]
    fn derived_instance_uuid_is_stable_within_the_process() {
        let a = derived_instance_uuid("g");
        assert_eq!(a, derived_instance_uuid("g"));
        assert_ne!(a, derived_instance_uuid("g3"));
        // The instance namespace is a v5 UUID derived from random data.
        assert_eq!(instance_uuid().get_version_num(), 5);
    }
}
